    // Use stringstream to easily iterate through words in the line
    stringstream ss(line);
    string word;

    // Extract words from the line
    while (ss >> word) {
      // Convert both the word and the target word to lowercase for case-insensitive comparison
      for (char &c : word) {
        c = tolower(c);
      }
      for (char &c : wordToCount) {
        c = tolower(c);
      }

      // Compare the words
      if (word == wordToCount) {
        count++;
      }
    }
  }

  // Close the file
  inputFile.close();

  // Print the result
  cout << "The word \"" << wordToCount << "\" appears " << count << " times in the file." << endl;

  return 0;
}
